import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"9、【小畜】 乾下巽上","description":"橫渠易說 - 9、【小畜】 乾下巽上","frontmatter":{"title":"9、【小畜】 乾下巽上","description":"橫渠易說 - 9、【小畜】 乾下巽上"},"headers":[],"relativePath":"classics/hengqu/011.md","filePath":"classics/hengqu/011.md"}'),l={name:"classics/hengqu/011.md"};function t(n,a,s,d,c,o){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_9、【小畜】-乾下巽上" tabindex="-1">9、【小畜】 乾下巽上 <a class="header-anchor" href="#_9、【小畜】-乾下巽上" aria-label="Permalink to “9、【小畜】 乾下巽上”">​</a></h1><p>#小畜。亨。密雲不雨，自我西郊。</p><h3 id="彖曰-小畜-柔得位而上下應之曰小畜。健而巽-剛中而志行-乃亨。-密雲不雨-尚往也。-自我西郊-施未行也。" tabindex="-1">彖曰：小畜，柔得位而上下應之曰小畜。健而巽，剛中而志行，乃亨。“密雲不雨”，尚往也。“自我西郊”，施未行也。 <a class="header-anchor" href="#彖曰-小畜-柔得位而上下應之曰小畜。健而巽-剛中而志行-乃亨。-密雲不雨-尚往也。-自我西郊-施未行也。" aria-label="Permalink to “彖曰：小畜，柔得位而上下應之曰小畜。健而巽，剛中而志行，乃亨。“密雲不雨”，尚往也。“自我西郊”，施未行也。”">​</a></h3><h3 id="象曰-風行天上-小畜-君子以懿文德。" tabindex="-1">象曰：風行天上，小畜，君子以懿文德。 <a class="header-anchor" href="#象曰-風行天上-小畜-君子以懿文德。" aria-label="Permalink to “象曰：風行天上，小畜，君子以懿文德。”">​</a></h3><p>“自我西郊”，剛陽之氣進而不已也。</p><h3 id="初九-復自道-何其咎-吉。-象曰-復自道-其義吉也。" tabindex="-1">初九，復自道，何其咎，吉。 象曰：“復自道”，其義吉也。 <a class="header-anchor" href="#初九-復自道-何其咎-吉。-象曰-復自道-其義吉也。" aria-label="Permalink to “初九，復自道，何其咎，吉。 象曰：“復自道”，其義吉也。”">​</a></h3><p>以理而升，進之於應也。</p><h3 id="九二-牽復-吉。-象曰-牽覆在中-亦不自失也。" tabindex="-1">九二，牽復，吉。 象曰：牽覆在中，亦不自失也。 <a class="header-anchor" href="#九二-牽復-吉。-象曰-牽覆在中-亦不自失也。" aria-label="Permalink to “九二，牽復，吉。 象曰：牽覆在中，亦不自失也。”">​</a></h3><p>初反自道，三為說輻，二以匯徵在中，故未為失。</p><h3 id="九三-輿說輻-夫妻反目。-象曰-夫妻反目-不能正室也。" tabindex="-1">九三，輿說輻，夫妻反目。 象曰：“夫妻反目”，不能正室也。 <a class="header-anchor" href="#九三-輿說輻-夫妻反目。-象曰-夫妻反目-不能正室也。" aria-label="Permalink to “九三，輿說輻，夫妻反目。 象曰：“夫妻反目”，不能正室也。”">​</a></h3><p>近而相比，故說輻而不能進，反為柔制，故曰反目；非其偶也，故不能正其室。</p><h3 id="六四-有孚血去惕出-無咎。-象曰-有孚惕出-上合志也。" tabindex="-1">六四，有孚血去惕出，無咎。 象曰：“有孚惕出”，上合志也。 <a class="header-anchor" href="#六四-有孚血去惕出-無咎。-象曰-有孚惕出-上合志也。" aria-label="Permalink to “六四，有孚血去惕出，無咎。 象曰：“有孚惕出”，上合志也。”">​</a></h3><p>以陰居陰，其體不躁，故曰“有孚”。能上比於五，與之合志，雖為群下所侵，被傷而去，懷懼而出，於義無咎。</p><h3 id="九五-有孚攣如-富以其鄰。-象曰-有孚攣如-不獨富也。" tabindex="-1">九五，有孚攣如，富以其鄰。 象曰：“有孚攣如”，不獨富也。 <a class="header-anchor" href="#九五-有孚攣如-富以其鄰。-象曰-有孚攣如-不獨富也。" aria-label="Permalink to “九五，有孚攣如，富以其鄰。 象曰：“有孚攣如”，不獨富也。”">​</a></h3><h3 id="上九-既雨既處-尚德載-婦貞厲。月幾望-君子徵-兇。-象曰-既雨既處-德積載也。-君子徵兇-有所疑也。" tabindex="-1">上九，既雨既處，尚德載，婦貞厲。月幾望，君子徵，兇。 象曰：“既雨既處”，德積載也。“君子徵兇”，有所疑也。 <a class="header-anchor" href="#上九-既雨既處-尚德載-婦貞厲。月幾望-君子徵-兇。-象曰-既雨既處-德積載也。-君子徵兇-有所疑也。" aria-label="Permalink to “上九，既雨既處，尚德載，婦貞厲。月幾望，君子徵，兇。 象曰：“既雨既處”，德積載也。“君子徵兇”，有所疑也。”">​</a></h3><p>六四為眾陽之主，己能接之以信，攣如不疑，則亦為眾所歸，故曰“富以其鄰”。</p>',16)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
